clc; clear;

% -------- Plant --------
m1=3; m2=5; c1=2; c2=5; k1=4; k2=12;
A=[0 1 0 0;
   -(k1+k2)/m1 -(c1+c2)/m1  k2/m1  c2/m1;
   0 0 0 1;
   k2/m2 c2/m2 -k2/m2 -c2/m2];
B=[0;1/m1;0;0];

% -------- Reference --------
w = 2*pi*1;            % 1 Hz
Aref = 0.8;
r  = @(t) Aref*sin(w*t);
rd = @(t) Aref*w*cos(w*t);
rdd = @(t) -Aref*w^2*sin(w*t);

% -------- PID gains --------
Kp = 120;
Ki = 10;
Kd = 35;

% -------- Closed-loop ODE (PID + feedforward) --------
% X = [x1 x1dot x2 x2dot I]^T
f = @(t,X) [
    
    % --- CONTROL INPUT ----------------------------------------------------
    % PID part
    Kp*(r(t)-X(1)) + Ki*X(5) + Kd*(rd(t)-X(2)) ...
    % Feedforward part
    + m1*rdd(t) + c1*rd(t) + k1*r(t) ...
    + c2*(rd(t)-X(4)) + k2*(r(t)-X(3));
    % ----------------------------------------------------------------------
] .* B + A*X(1:4);
% ^ That gives d[x1; x1dot; x2; x2dot]

% Integral of error:
f = @(t,X) [ ...
    A*X(1:4) + B*( ...
        Kp*(r(t)-X(1)) + Ki*X(5) + Kd*(rd(t)-X(2)) ...
        + m1*rdd(t) + c1*rd(t) + k1*r(t) ...
        + c2*(rd(t)-X(4)) + k2*(r(t)-X(3)) ...
);
    r(t) - X(1)    % dI/dt
];

% -------- Simulate --------
tspan = [0 8];
X0 = [0 0 0 0 0]';
[t,X] = ode45(f,tspan,X0);

x1  = X(:,1);
ref = Aref*sin(w*t);

% -------- Plot --------
figure; plot(t,ref,'--',t,x1,'-','LineWidth',1.5); grid on %[output:9a625fce]
xlabel('Time (s)'); ylabel('x_1 (m)'); %[output:9a625fce]
legend('ref','x_1'); %[output:9a625fce]
title('PID + Full Feedforward Tracking'); %[output:9a625fce]
%%
A_aa = [0] %[output:191bc03e]
A_ab = [1 0 0] %[output:880a347b]
A_ba = [-(k2+k1)/m1 0 k2/m2]' %[output:7a1453f1]
A_bb = [-(c1+c2)/m1 k2/m1 c2/m1; %[output:group:1e80490e] %[output:457c73f6]
     0 0 1; %[output:457c73f6]
     c2/m2 -k2/m2 -c2/m2] %[output:group:1e80490e] %[output:457c73f6]

B_a = [0] %[output:33a111a0]
B_b = [0; 0; 1/m2] %[output:69645cd6]

C_a = [1] %[output:5f42a6bd]
C_b = [0 0 0] %[output:5fa3fddd]
p_o = [-5.9 -5.8 -1];
Ke = place(A_bb', A_ab', p_o)';
A_hat = A_bb - Ke*A_ab %[output:7ef9239c]
B_hat = A_hat*Ke + A_ba - Ke*A_aa %[output:25a2fc37]
F_hat = B_b - Ke*B_a %[output:13ee399a]
C_hat = [zeros(1, 3);   %[output:group:94a89b4d] %[output:54aee4e1]
         eye(3)] %[output:group:94a89b4d] %[output:54aee4e1]
D_hat = [1;             %[output:group:5f4b96a2] %[output:78a8ef54]
         Ke] %[output:group:5f4b96a2] %[output:78a8ef54]

C = eye(4) %[output:035c69ae]
D = zeros(4,1) %[output:15eb7942]
z0 = [2; 1.5; 1];
% Observer gain
x0 = [1; 0; -1; 0]; % Initial state: m1 pulled, m2 pushed

